{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "MoreMenu",
    "displayName": "More Menu",
    "category": "Action",
    "keywords": [
      "moremenu",
      "overflow",
      "kebab",
      "dotmenu",
      "threedot",
      "ellipsis",
      "dropdown",
      "contextmenu",
      "actionmenu"
    ],
    "props": [
      {
        "name": "items",
        "type": "DropdownMenuOption[]",
        "description": "Menu items: data array of actions, dividers, and sections. Same type as DropdownMenu items prop.",
        "required": true
      },
      {
        "name": "label",
        "type": "string",
        "description": "Accessible label for the trigger button (aria-label) and tooltip text.",
        "default": "'More options'"
      },
      {
        "name": "variant",
        "type": "ButtonVariant",
        "description": "Visual style variant of the trigger button.",
        "default": "'ghost'"
      },
      {
        "name": "size",
        "type": "ButtonSize",
        "description": "Size of the trigger button.",
        "default": "'md'"
      },
      {
        "name": "icon",
        "type": "ReactNode",
        "description": "Override the default three-dot icon. Accepts any ReactNode.",
        "slotElements": [
          {
            "__element": "Icon",
            "props": {
              "icon": "check",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Whether the menu trigger is disabled.",
        "default": "false"
      },
      {
        "name": "placement",
        "type": "'above' | 'below' | 'start' | 'end'",
        "description": "Position of the menu relative to the trigger. Logical: start/end resolve against the menu's own inherited direction (RTL mirrors).",
        "default": "'below'"
      },
      {
        "name": "alignment",
        "type": "'start' | 'center' | 'end'",
        "description": "Alignment along the placement axis. Use 'end' to align the menu with the trigger's trailing edge, which is usually what an overflow menu wants.",
        "default": "'start'"
      },
      {
        "name": "presentation",
        "type": "'popover' | 'bottom-sheet' | 'adaptive'",
        "description": "Presentation policy forwarded to DropdownMenu. `adaptive` keeps the anchored popover on pointer-based layouts and uses a BottomSheet on a compact touch screen: a coarse primary pointer, and a viewport narrower than the theme `md` breakpoint (768px by default) or shorter than 500px. Omitted, the menu is the anchored popover, and under a finger, on every device, the finger that opened it picks a row only after moving 10 px. Pass 'popover' to keep the pointer behavior on every device, the settle rule included."
      },
      {
        "name": "onOpenChange",
        "type": "(isOpen: boolean) => void",
        "description": "Callback fired when the menu opens or closes."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value, not an inline style object like style={{}}."
      }
    ],
    "playground": {
      "defaults": {
        "items": [
          {
            "label": "Edit",
            "value": "edit"
          },
          {
            "label": "Duplicate",
            "value": "duplicate"
          },
          {
            "label": "Delete",
            "value": "delete"
          }
        ]
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-more-menu"
        }
      ]
    },
    "usage": {
      "anatomy": [
        {
          "name": "Trigger button",
          "required": true,
          "description": "Icon-only Button that provides the visible overflow-menu entry point."
        },
        {
          "name": "Icon-resolved trigger icon",
          "required": false,
          "description": "Default semantic three-dot artwork resolved from the active Icon registry."
        },
        {
          "name": "Caller-rendered trigger content",
          "required": false,
          "description": "Arbitrary React content supplied directly as the trigger icon override."
        },
        {
          "name": "Menu surface",
          "required": true,
          "description": "DropdownMenu panel that also carries MoreMenu’s current public target."
        },
        {
          "name": "Pointer action row",
          "required": false,
          "description": "Action or nested-action trigger row rendered by DropdownMenu in the anchored presentation."
        },
        {
          "name": "Touch action row",
          "required": false,
          "description": "ListItem button rendered by DropdownMenu in the BottomSheet presentation."
        }
      ],
      "description": "MoreMenu is a three-dot button that opens a list of actions. Use it for secondary actions that don't need to be always visible, like in table rows, card headers, or toolbars.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use for overflow or secondary actions; keep primary actions visible outside the menu."
        },
        {
          "guidance": true,
          "description": "Use dividers or sections to group related actions when the menu has many items."
        },
        {
          "guidance": true,
          "description": "Use `presentation=\"adaptive\"` when the visible overflow trigger should open a thumb-reachable BottomSheet on compact touch devices."
        },
        {
          "guidance": false,
          "description": "Hide primary actions inside a MoreMenu; they should be directly visible."
        }
      ]
    },
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/MoreMenu",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
